// Multiblock Preview: explicit KubeJS registrations.
// Every structure below is registered only through MBPreviewEvents.registerPreview.
// Edit or remove individual registrations here; no Java/MI registry scan is used.

// 按 README「注册接口」编写：create / name / controller / patternFacing / controllerFacing / layeredShape / key / hatch / facing / controllerModelData / register。
// 方向修改位置（越靠近具体方块的设置优先级越高）：
// 1. 下方 MBP_DEFAULT_BLOCK_FACING / MBP_DEFAULT_CONTROLLER_FACING 是全部结构的默认方向。
// 2. allFacing(...) 覆盖某个结构的全部普通方块；controllerFacing(...) 只覆盖该结构的主方块。
// 3. keyRegex('字符', '^modid:.*_casing$') 可按完整方块 ID 批量加入候选；key 也接受 '/正则/' 字符串。
// 4. facing('字符', ...) 覆盖该字符的首选方块和全部候选；candidateFacing(...) 只覆盖一个候选方块。
// 5. patternFacing(...) 只控制 layeredShape 的展开方向，不控制任何方块模型朝向。
// 5. 世界投影会在上述规范方向基础上，继续按照世界中控制器的实际水平朝向旋转。
// MI 机器的正面由 ModelData 决定，普通 BlockState.facing 可能无效；controllerModelData(MBP_MODEL_DATA)
// 会接收依赖库计算出的最终主方块方向，因此应保留在每个 MI 机器注册末尾。
// 不需要（或想排除这一层）就把 MBP_USE_MODEL_DATA 改成 false。
// 注意：KubeJS 的 Rhino 会把函数体内的 const/let 泄漏到脚本作用域，同名再声明就报 redeclaration，
// 所以这里全部用脚本级变量赋值，函数体内不写任何声明。
const MBP_USE_MODEL_DATA = true
let MBP_MODEL_DATA = null
let MBP_MODEL_DATA_INSTANCE = null
let MBP_PREVIEW_MODEL_DATA = null
let MBP_MACHINE_MODEL_DATA = null
if (MBP_USE_MODEL_DATA) {
    try {
        MBP_PREVIEW_MODEL_DATA = Java.loadClass('net.neoforged.neoforge.client.model.data.ModelData')
        MBP_MACHINE_MODEL_DATA = Java.loadClass('aztech.modern_industrialization.machines.models.MachineModelClientData')
        MBP_MODEL_DATA = facing => {
            MBP_MODEL_DATA_INSTANCE = new MBP_MACHINE_MODEL_DATA()
            MBP_MODEL_DATA_INSTANCE.frontDirection = facing
            return MBP_PREVIEW_MODEL_DATA.builder().with(MBP_MACHINE_MODEL_DATA.KEY, MBP_MODEL_DATA_INSTANCE).build()
        }
        console.info('[mbpreview] 控制器 ModelData 回调已启用')
    } catch (err) {
        console.warn('[mbpreview] 控制器模型数据不可用（服务端或未装 MI），使用默认模型: ' + err)
    }
}
let mbpPreview = null
let MBP_HATCH_TYPES = null

// 全局默认：修改这里会影响下方所有通过 mbpCreate 创建、且没有单独覆盖方向的结构。
const MBP_DEFAULT_BLOCK_FACING = 'north'
const MBP_DEFAULT_CONTROLLER_FACING = 'south'
function mbpCreate(event, id) {
    event.defaultFacing(MBP_DEFAULT_BLOCK_FACING)
    event.defaultControllerFacing(MBP_DEFAULT_CONTROLLER_FACING)
    return event.create(id)
}

// 功能仓必须同时注册提示文字和实际候选方块。这里按完整方块 ID 延迟匹配，
// 会包含 MI 自带、整合包 KJS 注册的量子/组合仓，以及 MI AE Addon 的对应功能方块。
function mbpHatch(preview, symbol) {
    MBP_HATCH_TYPES = Array.prototype.slice.call(arguments, 2)
    preview.hatch(symbol, MBP_HATCH_TYPES)
    if (MBP_HATCH_TYPES.indexOf('item_input') >= 0) {
        preview.keyRegex(symbol, '^modern_industrialization:.*item.*input_hatch$')
        preview.keyRegex(symbol, '^mi_ae_addon:(me_stocking_item_input_hatch|me_stocking_output_input_assembly|giant_input_assembly)$')
    }
    if (MBP_HATCH_TYPES.indexOf('item_output') >= 0) {
        preview.keyRegex(symbol, '^modern_industrialization:.*item.*output_hatch$')
        preview.keyRegex(symbol, '^mi_ae_addon:me_output_assembly$')
    }
    if (MBP_HATCH_TYPES.indexOf('fluid_input') >= 0) {
        preview.keyRegex(symbol, '^modern_industrialization:.*fluid.*input_hatch$')
        preview.keyRegex(symbol, '^mi_ae_addon:(me_stocking_fluid_input_hatch|me_stocking_output_input_assembly|giant_input_assembly)$')
    }
    if (MBP_HATCH_TYPES.indexOf('fluid_output') >= 0) {
        preview.keyRegex(symbol, '^modern_industrialization:.*fluid.*output_hatch$')
        preview.keyRegex(symbol, '^mi_ae_addon:me_output_assembly$')
    }
    if (MBP_HATCH_TYPES.indexOf('chemical_input') >= 0) {
        preview.keyRegex(symbol, '^mi_ae_addon:(me_stocking_chemical_input_hatch|me_stocking_output_input_assembly|giant_input_assembly)$')
    }
    if (MBP_HATCH_TYPES.indexOf('chemical_output') >= 0) {
        preview.keyRegex(symbol, '^mi_ae_addon:me_chemical_output_hatch$')
    }
    if (MBP_HATCH_TYPES.indexOf('energy_input') >= 0) {
        preview.keyRegex(symbol, '^modern_industrialization:.*energy_input_hatch$')
    }
    if (MBP_HATCH_TYPES.indexOf('energy_output') >= 0) {
        preview.keyRegex(symbol, '^modern_industrialization:.*energy_output_hatch$')
    }
}

