// bigger_ambient_gas_collector.js — 87 方块
MBPreviewEvents.registerPreview(event => {
    try {
        mbpPreview = mbpCreate(event, 'modern_mekanistics:bigger_ambient_gas_collector')
        mbpPreview.name("更大的环境气体收集器")
        mbpPreview.controller('modern_mekanistics:bigger_ambient_gas_collector')
        // 结构展开方向：如果整个结构跑到控制器正面，将 south 改回 north（反之亦然）。
        mbpPreview.patternFacing('south')
        // 主方块模型朝结构外侧；不要用 patternFacing 修正模型贴图方向。
        mbpPreview.controllerFacing('north')
        mbpPreview.layeredShape([
    [" aaa ", " cdc ", " dbd ", "bbbbb"],
    ["accca", "ceeec", "dfffd", "bgggb"],
    ["accca", "deeed", "bfffb", "bgggb"],
    ["accca", "ceeec", "dfffd", "bgggb"],
    [" aaa ", " cdc ", " d#d ", "bbbbb"],
  ])
        mbpPreview.key('a', 'pneumaticcraft:pressure_chamber_valve')
        mbpPreview.key('b', 'pneumaticcraft:pressure_chamber_glass')
        mbpPreview.key('c', 'pneumaticcraft:compressed_iron_block')
        mbpPreview.key('d', 'pneumaticcraft:plastic_brick_white')
        mbpPreview.key('e', 'mekmm:ambient_gas_collector')
        mbpPreview.key('f', 'xycraft_machines:extractor')
        mbpPreview.key('g', 'pneumaticcraft:reinforced_pressure_chamber_valve')
        mbpHatch(mbpPreview, 'd', 'item_input', 'chemical_output', 'energy_input')
        // 单独覆盖示例（需要时取消注释）：
        // mbpPreview.allFacing('south')
        // mbpPreview.facing('d', 'east')
        // mbpPreview.candidateFacing('d', 'pneumaticcraft:plastic_brick_white', 'west')
        // MI 控制器必须保留此回调，依赖库会把上面的 controllerFacing 同步给动态模型。
        if (MBP_MODEL_DATA) mbpPreview.controllerModelData(MBP_MODEL_DATA)
        mbpPreview.register()
    } catch (err) { console.error('[mbpreview] modern_mekanistics:bigger_ambient_gas_collector 注册失败: ' + err) }
})

